use std::{fs,path::Path,collections::{BTreeSet,BTreeMap}};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const ROOT:&str="/home/ubuntu/src/zopro-perf-work/group-probe218";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn med(mut a:[f64;3])->f64{a.sort_by(f64::total_cmp);a[1]}
fn close(a:f64,b:f64){assert!((a-b).abs()<=1e-10*a.abs().max(b.abs()).max(1.));}
fn main(){let root=Path::new(ROOT);let result=read(root.join("result.json"));let jobs=read(root.join("jobs.json"));let mut rows=BTreeMap::new();let mut ledger:BTreeSet<String>=serde_json::from_value(read("/home/ubuntu/src/zopro-perf-work/group-stack217/proof-sha256-after-audit.json")).unwrap();let mut receipts=0;let mut records=0;for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let smoke=j["smoke"]==true;let d=root.join(format!("{}-run/{name}",if smoke{"smoke"}else{"main"}));let vd=root.join(format!("{}-run/verify-{name}",if smoke{"smoke"}else{"verify"}));for p in[&d,&vd]{let receipt=read(p.join("exit.json"));assert_eq!(receipt["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{s}.log"))),receipt[format!("{s}_sha256")]);}receipts+=1;}let out=fs::read_to_string(d.join("stdout.log")).unwrap();let mut samples=vec![];let mut summary=None;for line in out.lines(){if let Some(s)=line.strip_prefix("SAMPLE "){let v:Value=serde_json::from_str(s).unwrap();assert_eq!(v["round"],samples.len());samples.push(v["ms"].as_f64().unwrap());}if let Some(s)=line.strip_prefix("SUMMARY "){assert!(summary.is_none());summary=Some(serde_json::from_str::<Value>(s).unwrap());}}let n=j["rounds"].as_u64().unwrap()as usize;assert_eq!(samples.len(),n);records+=n;let summary=summary.unwrap();let mean=samples.iter().fold(0.,|sum,x|sum+x)/n as f64;let cpu=(summary["user_cpu_ms"].as_f64().unwrap()+summary["system_cpu_ms"].as_f64().unwrap())/n as f64;let rss=summary["whole_process_maxrss_kib"].as_f64().unwrap()/1024.;let recorded=result["rows"].as_array().unwrap().iter().find(|r|r["job"]["name"]==name).unwrap();close(mean,recorded["mean_ms"].as_f64().unwrap());close(cpu,recorded["cpu_ms"].as_f64().unwrap());close(rss,recorded["peak_rss_mib"].as_f64().unwrap());if !smoke{rows.insert((j["mode"].as_str().unwrap().to_string(),j["block"].as_u64().unwrap()as usize),(mean,cpu,rss));}let proofdir=Path::new(j["proof_dir"].as_str().unwrap());let proof=hash(proofdir.join("0.proof"));assert!(ledger.insert(proof.clone()));assert_eq!(hash(proofdir.join("0.public")),j["public_sha256"]);let verifier=fs::read_to_string(vd.join("stdout.log")).unwrap();assert!(verifier.contains(&format!("VERIFIED proof_sha256={proof} ")));}
let value=|m:&str,b:usize|rows[&(m.to_string(),b)];let mut ready=true;let mut contrasts=vec![];for control in["STD","HB"]{let ratios=std::array::from_fn::<_,3,_>(|b|value("RAW",b).0/value(control,b).0);let cpu=med(std::array::from_fn(|b|value("RAW",b).1/value(control,b).1));let peak=|m:&str|(0..3).map(|b|value(m,b).2).max_by(f64::total_cmp).unwrap();let wins=ratios.iter().filter(|&&x|x<1.).count();let pass=med(ratios)<1.&&wins>=2&&cpu<=1.02&&peak("RAW")<=1.10*peak(control)+8.;ready&=pass;let recorded=result["comparisons"].as_array().unwrap().iter().find(|v|v["control"]==control).unwrap();close(med(ratios),recorded["paired_median"].as_f64().unwrap());assert_eq!(recorded["pass"],pass);contrasts.push(json!({"control":control,"ratios":ratios,"pass":pass}));}let calibration=med(std::array::from_fn(|b|value("HB",b).0/value("STD",b).0));ready&=(1./1.03..=1.03).contains(&calibration);assert_eq!(result["ready_for_qualification"],ready);let mut changed=vec![];let mut exact=0;let old=read("/home/ubuntu/src/zopro-perf-work/group-profile216/source/.xtask/source-pins.json");for(p,h)in old.as_object().unwrap(){let rel=p.strip_prefix("/home/ubuntu/src/zopro-perf-work/group-profile216/source/").unwrap();if hash(root.join("source").join(rel))==h.as_str().unwrap(){exact+=1;}else{changed.push(rel);}}assert_eq!(changed,["Cargo.lock","crates/zopro-core/Cargo.toml","crates/zopro-core/src/msm_affine/grouping.rs"]);let before=fs::read_to_string("/home/ubuntu/src/zopro-perf-work/group-profile216/source/crates/zopro-core/src/msm_affine/grouping.rs").unwrap();let current=fs::read_to_string(root.join("source/crates/zopro-core/src/msm_affine/grouping.rs")).unwrap();let dispatch="    match std::env::var(\"ZOPRO_CPU_GROUP_PROBE\").as_deref() {\n        Ok(\"HB\")=>return owned_probe::build::<false>(scalars,capacity,percent,reservation),\n        Ok(\"RAW\")=>return owned_probe::build::<true>(scalars,capacity,percent,reservation),\n        _=>{}\n    }\n";assert_eq!(before,current.replace(dispatch,"").strip_suffix("\nmod owned_probe;\n").unwrap());assert_eq!(ledger.len(),59046);let stored:BTreeSet<String>=serde_json::from_value(read(root.join("proof-sha256-after-main.json"))).unwrap();assert_eq!(ledger,stored);assert_eq!(records,2262);assert_eq!(receipts,24);let out=json!({"pass":true,"ready_for_qualification":ready,"independent_contrasts":contrasts,"source216_exact":exact,"source216_changed":changed,"source216_default_construction_retained":true,"receipts":receipts,"stream_hashes":receipts*2,"records":records,"fresh_Gnark_exports":12,"canonical_count":ledger.len(),"canonical_sha256":hash(root.join("proof-sha256-after-main.json"))});let p=root.join("review.json");assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Independent reader PASS; qualificationready={ready};{receipts}receipts;ledger{}",ledger.len());}
